raw:
{
  "spells": [
    {
      "id": "spell_earth_01",
      "theory": "辨壤术将魔力沿指尖渗入一把土中，借土粒对魔力的导引差异分辨粗细、干湿与混杂物。它只作用于手中或近处的一小撮土，不能追溯土来自哪块地，也不能读取地契或地界石上的归属记录。若土中掺有碎石、草根或灰烬，魔力会被分散，所得判断便偏向混杂后的整体质地。",
      "casting": "单膝蹲下，用食指与中指捻起一撮土，闭眼将魔力缓缓压入土粒之间，保持三次呼吸后睁眼。",
      "failure": "魔力滞在土表无法渗入，指尖只感到湿冷，土粒没有回应。若强行加力，土会从指缝散落，混入周围沙砾，此后连原本的质地也难再分辨。",
      "counters": [
        "向土中拌入大量细沙，使魔力导引趋于均匀，质地差异被掩盖。",
        "在土面洒一层草木灰，灰烬先吸收魔力，施术者只读到灰的松散。"
      ],
      "socialConsequences": "河谷农人常请人辨明新翻地块的土质，以便决定种粟还是种豆，乡约见证下收取少量谷粮作酬。陶工和烧砖人会借此挑选细腻黏土，但若在他人田里取土，须先得到田主同意。城市泥瓦匠看重这种判断，却不会仅凭一撮土就断定整批料可用，仍要亲自筛洗。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练时只能大致区分沙土与黏土，常把湿土判成干土。",
        "熟练度过百后，能辨出腐殖土与矿质土的基本比例。",
        "三百点以上时，可察觉土中盐分或石灰带来的细微涩感。",
        "六百点以上者判断稳定，仍只限一撮土，不越出材质范围。"
      ]
    },
    {
      "id": "spell_earth_02",
      "theory": "松土术把魔力压入耕土表层，使土粒间吸附的水膜暂时松动，颗粒因此彼此滑开。它只松动一小片土壤，不能搬走石块，也不能代替播种、施肥或开沟。若土中根系密集或含水过多，魔力会被根须和积水分散，松开的深度和均匀度都会下降，需要人力补锄。",
      "casting": "双手掌心朝下平贴土面，十指分开如耙齿，缓慢将魔力推入土中，同时向后挪动半步。",
      "failure": "魔力只在土面打转，留下几道浅痕便散掉，土块依旧紧实。若用力过猛，局部土粒会被推挤成硬团，反而比原先更难锄开，须用锄头重新敲碎。",
      "counters": [
        "在土面泼足水使颗粒黏连，魔力难以推开已饱和的土粒。",
        "向土中插入木桩或石块，阻断魔力在表层连续传导的路径。"
      ],
      "socialConsequences": "河谷春耕时，乡约允许会此术的人在自家田或经田主同意的地块上松土，换取帮工饭食。城市园圃的种植者会请人处理花床，但不会用它替代翻整石板缝里的老根。港口货栈外的泥地若被私自松动，可能影响堆货地基，货主会要求恢复原状并追究因此滑塌的货损。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时松开的土面深浅不一，常留下未破的硬块。",
        "过百点后，手掌覆盖范围内松土较为均匀，仍不排石。",
        "三百点以上时，能控制松土只停在表层，不搅动深处老根。",
        "六百点以上者动作稳定，松土范围仍限于双掌所及之处。"
      ]
    },
    {
      "id": "spell_earth_03",
      "theory": "压印术把魔力聚在脚掌或模具边缘，使软土在短暂时间内变得更易塑形，从而留下清晰足印或印模。它只改变软土表层的可塑性，不能把硬地变软，也不能在石面或木板上留下痕迹。若土中砂砾过多，魔力会被砾石棱角割散，印出的纹路便残缺不全，需要事后修补。",
      "casting": "将脚掌或刻好纹样的木模对准位置，单膝微屈，以脚跟为轴向下压出魔力，停一息后垂直提起。",
      "failure": "魔力未能聚在接触边缘，土面只被压出模糊凹坑，纹路很快被周围碎土填平。若提起时歪斜，印模一侧会塌陷，足印则拖出多余长痕，难以作为凭证。",
      "counters": [
        "在软土上撒一层干沙，沙粒隔开魔力，印痕边缘无法清晰成形。",
        "用木板平压土面，抹平已塑形的表层，使纹路重新模糊。"
      ],
      "socialConsequences": "河谷乡约在见证借贷或换工时，会让双方在软土上留下手印或足印，压印术使凭据更清楚，但地契本身仍须另立。城市巡夜人用清晰足印追查夜盗，若在私人庭院取印，须先得到屋主同意。港口理货人用印模标记货堆位置，若有人私自压印伪造货位，会按航运事故追究责任并赔偿错运货损。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时刻印深浅不均，细纹常被周围碎土盖住。",
        "过百点后，足印与模具纹路能保持基本完整，便于比对。",
        "三百点以上时，可在软土上连续压出深浅一致的印痕。",
        "六百点以上者提模干净利落，仍只在软土表层留印。"
      ]
    }
  ]
}
